from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data, sequence_first=False, discounted_tax=False):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            key = (seq, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        base = net if discounted_tax else raw
        tax = _round(base * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {}
    for name in names:
        rows[name] = {row["version"]: row for row in packages[name]
                      if row["version"] not in blocked.get(name, [])
                      and (name not in pins or row["version"] == pins[name])}
    choices = [[None] + [rows[name][v] for v in sorted(rows[name])]
               for name in names]

    def active_deps(row):
        return [d for d in row.get("deps", [])
                if not d.get("feature") or d.get("feature") in features]

    def is_acyclic(graph, installed):
        state = {}

        def visit(node):
            if state.get(node) == 1:
                return False
            if state.get(node) == 2:
                return True
            state[node] = 1
            for other in graph.get(node, []):
                if not visit(other):
                    return False
            state[node] = 2
            return True

        return all(visit(n) for n in installed)

    best_vector = None
    best = None
    for assignment in product(*choices):
        installed = {name: row for name, row in zip(names, assignment) if row is not None}
        versions = {name: row["version"] for name, row in installed.items()}
        valid = True
        graph = {}
        for name, row in installed.items():
            deps = active_deps(row)
            graph[name] = []
            for dep in deps:
                other = dep["name"]
                if other not in versions or not dep["min"] <= versions[other] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
            if not valid:
                break
        if not valid:
            continue
        roots = data["roots"]
        for name, bounds in roots.items():
            if name not in versions or not bounds[0] <= versions[name] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if reachable != set(installed) or not is_acyclic(graph, installed):
            continue
        vector = tuple(versions.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector, best = vector, versions
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _quota_intervals(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = tuple(sorted(j["id"] for j in subset))
        idset = set(ids)
        if not mandatory <= idset:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        intervals = sorted((j["start"], j["end"]) for j in subset)
        ends = []
        feasible = True
        for start, end in intervals:
            while ends and ends[0] <= start:
                heapq.heappop(ends)
            heapq.heappush(ends, end)
            if len(ends) > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(j["value"] for j in subset)
        if (best_value is None or value > best_value
                or (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [edge["duration"]]
            if remaining:
                durations.append(max(1, edge["duration"] - edge.get("discount", 0)))
            for index, duration in enumerate(durations):
                next_remaining = remaining - (index == 1)
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < dist.get(next_state, float("inf")):
                    dist[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda d: _ledger(d, False, False),
    "component_02": lambda d: _ledger(d, True, False),
    "component_03": lambda d: _ledger(d, False, True),
    "component_04": lambda d: _ledger(d, True, True),
    "component_05": lambda d: _ledger(d, False, False),
    "component_06": _dependency_resolver,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
